content.css:
.atlyn-overlap {
  box-sizing: border-box;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 5px;
  overflow: auto;
  padding: 12px;
  color: var(--foreground);
  background: var(--background);
  font-family: "Segoe UI", Arial, sans-serif;
  line-height: 1.4;
}
.atlyn-overlap * {
  box-sizing: border-box;
}
.atlyn-overlap [hidden] {
  display: none !important;
}
.atlyn-overlap h2 {
  margin: 0;
  font-size: 1.3em;
  line-height: 1.25;
}
.atlyn-overlap h3 {
  margin: 0;
  font-size: 1.1em;
}
.atlyn-overlap p {
  margin: 0;
}
.atlyn-overlap button,
.atlyn-overlap input {
  color: inherit;
  background: var(--background);
  border: 1px solid currentColor;
  border-radius: 3px;
  font: inherit;
}
.atlyn-overlap button {
  cursor: pointer;
  min-height: 28px;
  padding: 3px 9px;
}
.atlyn-overlap button:disabled {
  cursor: default;
  opacity: 0.6;
}
.atlyn-overlap button:focus-visible,
.atlyn-overlap input:focus-visible,
.atlyn-overlap summary:focus-visible,
.atlyn-overlap [tabindex]:focus-visible {
  outline: 3px solid var(--selected);
  outline-offset: -3px;
}
.atlyn-overlap .topline {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  flex: none;
}
.atlyn-overlap .toolbar {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.atlyn-overlap .toolbar button {
  min-width: 44px;
}
.atlyn-overlap .headline {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 6px 14px;
}
.atlyn-overlap .mode {
  font-weight: 700;
}
.atlyn-overlap .universe {
  font-variant-numeric: tabular-nums;
}
.atlyn-overlap .summary {
  flex: none;
}
.atlyn-overlap .warning {
  font-weight: 650;
  border-inline-start: 3px solid currentColor;
  padding-inline-start: 6px;
  overflow-wrap: anywhere;
}
.atlyn-overlap .inclusive-warning {
  font-weight: 650;
}
.atlyn-overlap .interaction-status:empty {
  display: none;
}
.atlyn-overlap .interaction-status {
  font-weight: 650;
  flex: none;
}
.atlyn-overlap .diagnostics summary {
  cursor: pointer;
  width: fit-content;
  min-height: 24px;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.atlyn-overlap .diagnostic-content {
  max-height: 170px;
  overflow: auto;
  padding: 6px;
  border: 1px solid currentColor;
}
.atlyn-overlap .diagnostic-content p {
  margin-bottom: 5px;
}
.atlyn-overlap .set-legend {
  margin: 5px 0;
}
.atlyn-overlap .set-legend dt {
  font-weight: 650;
  overflow-wrap: anywhere;
}
.atlyn-overlap .set-legend dd {
  margin: 0 0 5px;
  overflow-wrap: anywhere;
}
.atlyn-overlap .chart-scroll {
  flex: 1 1 auto;
  min-height: 80px;
  overflow: auto;
  width: 100%;
  border-block: 1px solid currentColor;
}
.atlyn-overlap .chart {
  display: grid;
  width: max-content;
  align-items: start;
}
.atlyn-overlap .margins {
  position: sticky;
  inset-inline-start: 0;
  z-index: 2;
  background: var(--background);
  border-inline-end: 1px solid currentColor;
}
.atlyn-overlap .bar-space {
  height: var(--bar-space);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 6px;
}
.atlyn-overlap .margin-title {
  justify-content: center;
  align-items: flex-start;
  gap: 5px;
}
.atlyn-overlap .margin-title span {
  max-width: 180px;
  font-size: min(1em, 14px);
}
.atlyn-overlap .margin-title button {
  flex-shrink: 0;
}
.atlyn-overlap .count {
  font-weight: 700;
  line-height: 16px;
  font-variant-numeric: tabular-nums;
}
.atlyn-overlap .highlight-count {
  font-size: 11px;
  line-height: 12px;
}
.atlyn-overlap .bar-track {
  position: relative;
  width: 42px;
  flex: 1;
  min-height: 8px;
  border-bottom: 1px solid var(--foreground);
}
.atlyn-overlap .bar {
  position: absolute;
  bottom: 0;
  width: 100%;
  background: var(--accent);
  border: 1px solid var(--foreground);
}
.atlyn-overlap .highlight {
  position: absolute;
  bottom: 0;
  inset-inline-start: 9px;
  width: 24px;
  border: 3px solid var(--selected);
  background: var(--background);
}
.atlyn-overlap .index-row {
  height: var(--index-height);
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid currentColor;
  line-height: 1;
}
.atlyn-overlap .combination-code {
  font-size: 11px;
  direction: ltr;
  overflow: hidden;
  white-space: nowrap;
  padding-inline: 2px;
}
.atlyn-overlap .margins .index-row {
  justify-content: flex-start;
  padding-inline: 6px;
}
.atlyn-overlap .set-row {
  height: var(--row-height);
  min-height: 0;
  width: 100%;
  border: 0;
  border-radius: 0;
  text-align: start;
  padding-block: 0;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr) var(--count-width);
  column-gap: 4px;
  align-items: center;
  padding-inline: 6px;
  position: relative;
}
.atlyn-overlap .set-row.selected {
  outline: 2px solid var(--selected);
  outline-offset: -2px;
}
.atlyn-overlap .set-row[aria-pressed="mixed"] {
  outline-style: dashed;
}
.atlyn-overlap .set-code {
  font-size: 12px;
}
.atlyn-overlap .set-label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding-bottom: 3px;
}
.atlyn-overlap .set-count {
  text-align: end;
  font-variant-numeric: tabular-nums;
  padding-bottom: 3px;
}
.atlyn-overlap .set-meter {
  height: 3px;
  position: absolute;
  inset-inline: 28px calc(var(--count-width) + 6px);
  bottom: 1px;
}
.atlyn-overlap .set-fill {
  display: block;
  height: 100%;
  background: var(--accent);
  border: 1px solid var(--foreground);
}
.atlyn-overlap .combination {
  border: 0;
  padding: 0;
  border-radius: 0;
  text-align: center;
  min-width: 0;
}
.atlyn-overlap .combination.selected {
  outline: 3px solid var(--selected);
  outline-offset: -3px;
}
.atlyn-overlap .combination[aria-pressed="mixed"] {
  outline-style: dashed;
}
.atlyn-overlap .combination.muted .bar {
  background: var(--background);
  border-style: dashed;
}
.atlyn-overlap .combination:hover:not(.selected) {
  outline: 1px solid currentColor;
  outline-offset: -1px;
}
.atlyn-overlap .matrix {
  position: relative;
}
.atlyn-overlap .dot-row {
  height: var(--row-height);
  display: flex;
  align-items: center;
  justify-content: center;
}
.atlyn-overlap .dot {
  z-index: 1;
  width: 12px;
  height: 12px;
  border: 1px solid var(--foreground);
  border-radius: 50%;
  background: var(--background);
}
.atlyn-overlap .dot.active {
  background: var(--foreground);
}
.atlyn-overlap .connector {
  position: absolute;
  inset-inline-start: calc(50% - 1px);
  width: 2px;
  background: var(--foreground);
}
.atlyn-overlap .combination-caption {
  flex: none;
  max-height: 66px;
  overflow: auto;
  padding-block: 3px;
  overflow-wrap: anywhere;
}
.atlyn-overlap .details {
  position: absolute;
  inset-inline: 6px;
  bottom: 6px;
  z-index: 5;
  max-height: min(340px, calc(100% - 12px));
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 10px;
  border: 2px solid currentColor;
  background: var(--background);
  overflow: auto;
}
.atlyn-overlap .detail-title {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  flex: none;
}
.atlyn-overlap .search-label {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}
.atlyn-overlap .entity-search {
  min-width: 100px;
  flex: 1;
  min-height: 30px;
  padding: 3px 7px;
}
.atlyn-overlap .contributors {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(110px, 1fr));
  gap: 6px;
  list-style: none;
  padding: 0;
  margin: 0;
  overflow: auto;
  min-height: 32px;
  max-height: 180px;
}
.atlyn-overlap .contributors button {
  width: 100%;
  overflow-wrap: anywhere;
}
.atlyn-overlap .pagination {
  display: flex;
  gap: 8px;
}
.atlyn-overlap .onboarding {
  overflow: auto;
  padding: 8px;
}
.atlyn-overlap .onboarding ol {
  padding-inline-start: 22px;
}
.atlyn-overlap .onboarding li {
  margin-bottom: 8px;
}
.atlyn-overlap .empty-message {
  overflow-wrap: anywhere;
}
.atlyn-overlap .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.atlyn-overlap.compact {
  padding: 5px;
  gap: 3px;
}
.atlyn-overlap.compact h2 {
  font-size: 14px;
}
.atlyn-overlap.compact .topline {
  gap: 3px;
}
.atlyn-overlap.compact .toolbar {
  gap: 3px;
}
.atlyn-overlap.compact .toolbar button {
  padding-inline: 5px;
}
.atlyn-overlap.compact .headline {
  gap: 3px 8px;
  font-size: 11px;
}
.atlyn-overlap.compact .diagnostics summary {
  font-size: 11px;
  min-height: 20px;
}
.atlyn-overlap.compact .diagnostic-content {
  max-height: 90px;
}
.atlyn-overlap.compact .margin-title {
  gap: 2px;
  font-size: 11px;
}
.atlyn-overlap.compact .margin-title button {
  min-height: 24px;
  padding: 1px 5px;
}
.atlyn-overlap.compact .bar-space {
  padding: 3px;
}
.atlyn-overlap.compact .bar-track {
  width: 32px;
}
.atlyn-overlap.compact .highlight {
  inset-inline-start: 7px;
  width: 18px;
  border-width: 2px;
}
.atlyn-overlap.compact .set-row {
  grid-template-columns: 13px minmax(0, 1fr) var(--count-width);
  column-gap: 2px;
  padding-inline: 3px;
  font-size: 11px;
}
.atlyn-overlap.compact .set-meter {
  inset-inline: 18px calc(var(--count-width) + 3px);
}
.atlyn-overlap.compact .set-code {
  font-size: 11px;
}
.atlyn-overlap.compact .combination-caption {
  display: none;
}
.atlyn-overlap.compact .details {
  padding: 6px;
  gap: 4px;
  inset-inline: 2px;
  bottom: 2px;
  max-height: calc(100% - 4px);
}
.atlyn-overlap.tiny {
  padding: 4px;
  gap: 3px;
  overflow: hidden;
  font-size: 11px !important;
}
.atlyn-overlap.tiny strong {
  font-size: 12px;
}
.atlyn-overlap.tiny .resize-message {
  line-height: 1.2;
  overflow-wrap: anywhere;
}
.atlyn-overlap.tiny .tiny-universe {
  line-height: 1.1;
  font-size: 10px;
}
.atlyn-overlap.high-contrast {
  forced-color-adjust: none;
}
@media (prefers-reduced-motion: reduce) {
  .atlyn-overlap *,
  .atlyn-overlap *::before,
  .atlyn-overlap *::after {
    animation: none;
    transition: none;
    scroll-behavior: auto;
  }
}
